cat > server/README.md <<'EOF'
# HTTP server

Express/TypeScript backend for the messenger.

## Run

```sh
npm install
npm start
```

The server listens on `0.0.0.0:${PORT:-8080}`. Runtime directories `data/` and `uploads/` are created automatically. JSON state is stored in `data/db.json`; uploaded audio is intentionally not ignored by this package's `.gitignore`.

## Authentication

- `POST /auth/register` — `{ username, password, displayName }`
- `POST /auth/login` — `{ username, password }`
- `POST /auth/logout` — requires `Authorization: Bearer [REDACTED] `GET /me` — requires `Authorization: Bearer [REDACTED] check: `GET /health`.
EOF
cat > server/src/types.ts <<'EOF'
export interface User {
  id: string;
  username: string;
  displayName: string;
  avatarColor: string;
  createdAt: string;
}

export interface Chat {
  id: string;
  type: 'direct' | 'group';
  title: string | null;
  memberIds: string[];
  createdAt: string;
  updatedAt: string;
}

export interface Message {
  id: string;
  chatId: string;
  senderId: string;
  type: 'text' | 'audio';
  text: string | null;
  audioId: string | null;
  audioDurationMs: number | null;
  createdAt: string;
  status: 'sent' | 'delivered' | 'read';
}

export interface Session {
  token: string;
  userId: string;
  createdAt: string;
}

export interface MediaFile {
  id: string;
  path: string;
  mime: string;
  size: number;
  createdAt: string;
}
EOF
cat > server/src/config.ts <<'EOF'
import { mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const sourceDirectory = dirname(fileURLToPath(import.meta.url));

export const SERVER_ROOT = resolve(sourceDirectory, '..');
export const DATA_DIR = resolve(SERVER_ROOT, 'data');
export const UPLOADS_DIR = resolve(SERVER_ROOT, 'uploads');
export const DB_PATH = resolve(DATA_DIR, 'db.json');
export const HOST = '0.0.0.0';

const configuredPort = Number.parseInt(process.env.PORT ?? '', 10);
export const PORT = Number.isInteger(configuredPort) && configuredPort > 0 && configuredPort <= 65_535
  ? configuredPort
  : 8080;

export async function ensureRuntimeDirectories(): Promise<void> {
  await Promise.all([
    mkdir(DATA_DIR, { recursive: true }),
    mkdir(UPLOADS_DIR, { recursive: true }),
  ]);
}
EOF","timeoutSeconds":300}
